import { test } from 'node:test';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';
import { makeRepo, cleanup } from '../../../../../engine-tests/helpers.mjs';
import { buildContext } from '../../../../../engine/checks/helpers/repo-context.mjs';
import { loadDeclaredChecks } from '../../../../../engine/checks/helpers/pattern-rules.mjs';
import noEnforcementNarration from '../worldRules/no-enforcement-narration.mjs';

const run = (root) => noEnforcementNarration.run(buildContext({ root, mode: 'all' }));

const DEMO_PACK = {
  'packs/demo/pack.mjs': "export default { id: 'demo', prose: 'RULES.md', rules: [] };\n",
  'packs/demo/rule.mjs': "const rule = { id: 'demo-rule', run() { return []; } };\nexport default rule;\n",
};

test('pack-no-enforcement-narration: silent prose beside the pack\'s rule module passes', () => {
  const root = makeRepo({ changed: {
    ...DEMO_PACK,
    'packs/demo/RULES.md': '# Demo\n\nDo the work well.\n',
  } });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('pack-no-enforcement-narration: flags prose naming a rule the pack itself defines', () => {
  const root = makeRepo({ changed: {
    ...DEMO_PACK,
    'packs/demo/RULES.md': '# Demo\n\nThe `demo-rule` check enforces this.\n',
  } });
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.equal(findings[0].severity, 'blocking');
    assert.equal(findings[0].file, 'packs/demo/RULES.md');
    assert.equal(findings[0].line, 3);
    assert.match(findings[0].what, /names its own check rule "demo-rule"/);
  } finally { cleanup(root); }
});

test('pack-no-enforcement-narration: flags prose telling the reader to run the runner', () => {
  const root = makeRepo({ changed: {
    ...DEMO_PACK,
    'packs/demo/RULES.md': '# Demo\n\nWhen done, run `node .claudinite/checks/run.mjs`.\n',
  } });
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.match(findings[0].what, /checks runner/);
  } finally { cleanup(root); }
});

test('pack-no-enforcement-narration: the pack README (the rules catalog) is never scanned', () => {
  const root = makeRepo({ changed: {
    ...DEMO_PACK,
    'packs/demo/RULES.md': '# Demo\n\nDo the work well.\n',
    'packs/demo/README.md': '| Rule | How enforced |\n|---|---|\n| Do it | check `demo-rule` |\n',
  } });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

test('pack-no-enforcement-narration: a prose-less pack contributes nothing', () => {
  const root = makeRepo({ changed: {
    'packs/demo/pack.mjs': "export default { id: 'demo', prose: null, rules: [] };\n",
    'packs/demo/rule.mjs': "const rule = { id: 'demo-rule', run() { return []; } };\nexport default rule;\n",
  } });
  try {
    assert.equal(run(root).length, 0);
  } finally { cleanup(root); }
});

// --- pack-independence (declared barrier) ------------------------------------
// Built through the real path: a forbidReferences entry in this pack's own
// declared-checks.json, compiled by the declarative engine — packs-tree
// segregation is barrier data only, no code here checks anything.
const packIndependence = loadDeclaredChecks(fileURLToPath(new URL('..', import.meta.url)))
  .find((r) => r.id === 'pack-independence');

test('pack-independence: a cross-pack import fires; own files, the engine surface, and prose stay open', () => {
  const root = makeRepo({ changed: {
    'packs/a/pack.mjs': "import other from '../b/rule.mjs';\nimport own from './own.mjs';\nimport { finding } from '../../engine/checks/helpers/findings.mjs';\nimport { loadPacks } from '../registry.mjs';\n",
    'packs/a/own.mjs': 'export default 1;\n',
    'packs/a/README.md': 'Composes with [the b pack](../b/rule.mjs) by declaration.\n',
    'packs/b/rule.mjs': 'export default 1;\n',
    'engine/checks/helpers/findings.mjs': 'export const finding = 1;\n',
    'engine/pack_loader/pack-registry.mjs': 'export const loadPacks = 1;\n',
  } });
  try {
    const findings = packIndependence.run(buildContext({ root, mode: 'all' }));
    assert.equal(findings.length, 1);
    assert.equal(findings[0].file, 'packs/a/pack.mjs');
    assert.equal(findings[0].line, 1);
    assert.match(findings[0].what, /packs\/b/);
  } finally { cleanup(root); }
});

test('pack-independence: an import outside the engine surface fires; inert without a packs/ tree', () => {
  const crossing = makeRepo({ changed: {
    // A canon-internal tree that is never vendored — the crossing this rule exists
    // to catch. It was migrations/ until #768 Phase 5 deleted that tree; updates/ is
    // the same shape of target, and equally outside the engine surface a pack may import.
    'packs/a/mod.mjs': "import reg from '../../updates/pack-update.mjs';\n",
    'updates/pack-update.mjs': 'export default 1;\n',
  } });
  const consumer = makeRepo({ changed: {
    'src/app.mjs': "import x from './lib.mjs';\n",
    'src/lib.mjs': 'export default 1;\n',
  } });
  try {
    const f = packIndependence.run(buildContext({ root: crossing, mode: 'all' }));
    assert.equal(f.length, 1);
    assert.match(f[0].what, /updates\/pack-update\.mjs/);
    assert.equal(packIndependence.run(buildContext({ root: consumer, mode: 'all' })).length, 0);
  } finally { cleanup(crossing); cleanup(consumer); }
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { makeRepo, deletePath, cleanup } from '../../../../../engine-tests/helpers.mjs';
import { buildContext } from '../../../../../engine/checks/helpers/repo-context.mjs';
import promoteScope from '../promote-scope.mjs';

function run(root) {
  return promoteScope.run(buildContext({ root, mode: 'changed' }));
}

test('promote-scope: silent when the branch touches only packs/ and skills/', () => {
  const root = makeRepo({
    changed: {
      'packs/node/RULES.md': '- new rule\n',
      'skills/writing-tests/SKILL.md': 'updated\n',
    },
    commitMsg: 'promote Refs #1',
  });
  try {
    assert.deepEqual(run(root), []);
  } finally {
    cleanup(root);
  }
});

test('promote-scope: fires on a path outside packs/ and skills/', () => {
  const root = makeRepo({
    changed: {
      'packs/node/RULES.md': '- new rule\n',
      'engine/pack_loader/pack-registry.mjs': '// edited\n', // stray: engine machinery, off-limits to promote
    },
    commitMsg: 'promote Refs #1',
  });
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.equal(findings[0].file, 'engine/pack_loader/pack-registry.mjs');
    assert.equal(findings[0].rule, 'promote-scope');
  } finally {
    cleanup(root);
  }
});

// Per-user preferences do not live in this repo at all — they belong to a fleet's
// users, so item-routing sends them to the repo the `preferences` setting names. The
// gate is what stops a promote from quietly re-creating a canon-side home for them.
test('promote-scope: a canon-side per-user preferences path is out of bounds', () => {
  const root = makeRepo({
    changed: { 'preferences/someone@example.com.md': '- pref\n' },
    commitMsg: 'promote Refs #1',
  });
  try {
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.equal(findings[0].file, 'preferences/someone@example.com.md');
  } finally {
    cleanup(root);
  }
});

test('promote-scope: a deletion outside packs/ and skills/ is caught too', () => {
  const root = makeRepo({
    base: { 'engine/old.md': 'legacy\n' },
    changed: { 'packs/node/RULES.md': '- new rule\n' },
    commitMsg: 'promote Refs #1',
  });
  try {
    deletePath(root, 'engine/old.md', 'prune Refs #1');
    const findings = run(root);
    assert.ok(findings.some((f) => f.file === 'engine/old.md'));
  } finally {
    cleanup(root);
  }
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import promote from '../tasks/growth-promote/task.mjs';
import discover from '../tasks/growth-discover-packs/task.mjs';

// The canon-curation fleet-scoped task preconditions (per-project-scheduling
// DESIGN §6 table 2): growth-promote reads which members changed their local
// packs, growth-discover-packs sweeps the members' stacks for technologies the
// canon does not home. (prose-to-checks-sweep moved to claudinite-growth as a
// per-repo task; migration records need no curation task at all — they are kept
// forever, and vendoring's recency window decides what ships.)
// Each precondition is pure over the collected signals, so it tests directly
// against a fabricated `fleet` signal.

const member = (over = {}) => ({
  repo: 'acme/app', defaultBranch: 'main',
  activePacks: ['claudinite-growth'], packConfigs: {},
  hasLocalPacks: true, localPacksChanged: true, stamp: null, schedulesItself: false,
  ...over,
});

// --- growth-promote ----------------------------------------------------------

test('growth-promote: declaration is daily/opus/pr+nothing over the fleet signal', () => {
  assert.equal(promote.frequency, 'daily');
  assert.equal(promote.agent_model, 'opus');
  assert.equal(promote.expected_outcome, 'pr'); // owner-gated: its policy authorizes nothing to auto-merge
  assert.deepEqual(promote.precondition_signals, ['fleet']);
  // Same as discover: reach is the endpoint the hand-off calls, and this task reads
  // every member's local packs.
  assert.equal(promote.invocation_endpoint, 'fleet');
  assert.equal(promote.session_scope, undefined, 'session_scope lost its last reader with the slot scheduler');
});

test('growth-promote: fires on participating members whose local packs changed', () => {
  const v = promote.precondition({ fleet: { members: [
    member({ repo: 'acme/a' }),
    member({ repo: 'acme/b', localPacksChanged: false }), // changed nothing → excluded
    member({ repo: 'acme/c' }),
  ] } });
  assert.equal(v.run, true);
  assert.match(v.context.join(' '), /acme\/a/);
  assert.match(v.context.join(' '), /acme\/c/);
  assert.doesNotMatch(v.context.join(' '), /acme\/b/); // the unchanged member isn't a target
});

test('growth-promote: skips a member that opted out of promotion', () => {
  const v = promote.precondition({ fleet: { members: [
    member({ repo: 'acme/opt', packConfigs: { 'claudinite-growth': { promote: false } } }),
  ] } });
  assert.equal(v.run, false);
});

test('growth-promote: skips a member without local packs, or not declaring the growth pack', () => {
  assert.equal(promote.precondition({ fleet: { members: [member({ hasLocalPacks: false })] } }).run, false);
  assert.equal(promote.precondition({ fleet: { members: [member({ activePacks: ['basics'] })] } }).run, false);
});

test('growth-promote: skips when there is no fleet signal or the enumeration errored', () => {
  assert.equal(promote.precondition({ fleet: null }).run, false);
  assert.equal(promote.precondition({ fleet: { error: 'wrong token' } }).run, false);
  assert.equal(promote.precondition({ fleet: { members: [] } }).run, false);
});

// --- growth-discover-packs (the FLEET sweep) ---------------------------------
// Not to be confused with its per-repo namesake in claudinite-growth, which
// authors a repo's own LOCAL packs. This one is the central canon-gap sweep.

test('growth-discover-packs: declaration is weekly/opus/pr+nothing, fleet-reaching over the fleet signal', () => {
  assert.equal(discover.id, 'growth-discover-packs');
  assert.equal(discover.frequency, 'weekly');
  assert.equal(discover.agent_model, 'opus');
  assert.equal(discover.expected_outcome, 'pr'); // a new canon pack is owner-reviewed: its policy authorizes nothing to auto-merge
  // Reach is which endpoint the hand-off calls, and nothing else — this task reads
  // every member's tree, which an ordinary session in this repo does not.
  assert.equal(discover.invocation_endpoint, 'fleet');
  assert.equal(discover.session_scope, undefined, 'session_scope lost its last reader with the slot scheduler');
  assert.deepEqual(discover.precondition_signals, ['fleet']);
});

test('growth-discover-packs: sweeps every covered member, binding them as Context', () => {
  const v = discover.precondition({ fleet: { members: [
    member({ repo: 'acme/a', localPacksChanged: false }),          // no window trigger — the opportunity is standing
    member({ repo: 'acme/b', activePacks: ['basics'], hasLocalPacks: false }), // not a growth participant — still swept
  ] } });
  assert.equal(v.run, true);
  assert.match(v.context.join(' '), /acme\/a/);
  assert.match(v.context.join(' '), /acme\/b/);
  assert.match(v.context.join(' '), /do not enumerate the fleet yourself/i);
});

test('growth-discover-packs: skips a member that declares no packs', () => {
  const v = discover.precondition({ fleet: { members: [member({ repo: 'acme/bare', activePacks: [] })] } });
  assert.equal(v.run, false);
});

test('growth-discover-packs: skips when there is no fleet signal or the enumeration errored', () => {
  assert.equal(discover.precondition({ fleet: null }).run, false);
  assert.equal(discover.precondition({ fleet: { error: 'wrong token' } }).run, false);
  assert.equal(discover.precondition({ fleet: { members: [] } }).run, false);
});

